// ============================================================
// CONFIGURATION
// ============================================================
const KIE_API_KEY        = $env['KIE_API_KEY']        ?? 'PASTE_YOUR_KIE_API_KEY_HERE';
const BASEROW_TOKEN      = $env['BASEROW_TOKEN']       ?? 'PASTE_YOUR_BASEROW_TOKEN_HERE';
const BASEROW_TABLE_ID   = $env['BASEROW_TABLE_ID']    ?? 'YOUR_TABLE_ID';  // numeric ID from Baserow URL
const BASEROW_BASE_URL   = $env['BASEROW_BASE_URL']    ?? 'https://api.baserow.io'; // change if self-hosted

// URL of your character reference image (Rick, or whoever your character is).
// Upload your image anywhere public (Cloudinary, S3, Kie AI upload, etc.)
// and paste the direct URL here.
const CHARACTER_REF_URL  = $env['CHARACTER_REF_URL']   ?? 'PASTE_YOUR_CHARACTER_IMAGE_URL_HERE';

const KIE_BASE           = 'https://api.kie.ai/api/v1';
const POLL_INTERVAL_MS   = 5000;   // poll every 5 seconds
const MAX_POLL_ATTEMPTS  = 144;    // 12 minutes max per image
const SUBMIT_DELAY_MS    = 350;    // rate-limit buffer between submissions
const MAX_RETRIES        = 3;      // retry failed generations up to 3 times

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

// ── Baserow helpers ───────────────────────────────────────
const brHeaders = {
  Authorization: `Token ${BASEROW_TOKEN}`,
  'Content-Type': 'application/json',
};

async function brGet(path) {
  const res = await fetch(`${BASEROW_BASE_URL}${path}`, { headers: brHeaders });
  if (!res.ok) throw new Error(`Baserow GET ${path} → ${res.status}: ${await res.text()}`);
  return res.json();
}

async function brPatch(rowId, fields) {
  const res = await fetch(
    `${BASEROW_BASE_URL}/api/database/rows/table/${BASEROW_TABLE_ID}/${rowId}/?user_field_names=true`,
    { method: 'PATCH', headers: brHeaders, body: JSON.stringify(fields) }
  );
  if (!res.ok) throw new Error(`Baserow PATCH row ${rowId} → ${res.status}: ${await res.text()}`);
  return res.json();
}

// ── 1. Fetch all pending image-gen rows ───────────────────
// Expects your Baserow table to have these fields:
//   status      : text  (pending / processing / completed / failed)
//   mode        : text  (image_gen  ← only these rows are processed here)
//   image_prompt: text
//   image_url   : text  (filled in by this workflow)

let allRows = [];
let page = 1;
while (true) {
  const data = await brGet(
    `/api/database/rows/table/${BASEROW_TABLE_ID}/?user_field_names=true&size=200&page=${page}`
  );
  allRows = allRows.concat(data.results);
  if (!data.next) break;
  page++;
}

const pendingRows = allRows.filter(
  (r) => (r.status ?? '').toLowerCase() === 'pending' &&
          (r.mode   ?? '').toLowerCase() === 'image_gen'
);

if (pendingRows.length === 0) {
  return [{ json: { message: 'No pending image_gen rows found. Nothing to do.' } }];
}

// ── 2. Mark all as "processing" immediately ───────────────
for (const row of pendingRows) {
  await brPatch(row.id, { status: 'processing' });
  await sleep(100);
}

// ── 3. Submit all Kie AI tasks ────────────────────────────
const tasks = []; // { rowId, prompt, taskId, retries }

for (let i = 0; i < pendingRows.length; i++) {
  if (i > 0) await sleep(SUBMIT_DELAY_MS);
  const row = pendingRows[i];
  const prompt = row.image_prompt ?? row.prompt ?? '';

  if (!prompt) {
    await brPatch(row.id, { status: 'failed' });
    continue;
  }

  try {
    const res = await fetch(`${KIE_BASE}/jobs/createTask`, {
      method: 'POST',
      headers: { Authorization: `Bearer ${KIE_API_KEY}`, 'Content-Type': 'application/json' },
      body: JSON.stringify({
        model: 'nano-banana-2',
        input: {
          prompt,
          image_input: CHARACTER_REF_URL ? [CHARACTER_REF_URL] : [],
          aspect_ratio: 'auto',
          resolution: '1K',
          output_format: 'png',
        },
      }),
    });

    if (!res.ok) {
      console.error(`Row ${row.id}: createTask failed (${res.status})`);
      tasks.push({ rowId: row.id, prompt, taskId: null, retries: 0 });
      continue;
    }

    const json = await res.json();
    const taskId = json?.data?.taskId ?? json?.taskId;
    tasks.push({ rowId: row.id, prompt, taskId, retries: 0 });
  } catch (e) {
    console.error(`Row ${row.id}: submit error — ${e.message}`);
    tasks.push({ rowId: row.id, prompt, taskId: null, retries: 0 });
  }
}

// ── 4. Poll until all tasks complete ─────────────────────
const pollCount = {};
const pending = new Set(tasks.filter((t) => t.taskId).map((_, i) => i));
for (const i of pending) pollCount[i] = 0;

while (pending.size > 0) {
  await sleep(POLL_INTERVAL_MS);
  const done = [];

  for (const i of pending) {
    pollCount[i]++;
    if (pollCount[i] > MAX_POLL_ATTEMPTS) {
      console.error(`Task ${i} timed out`);
      done.push(i);
      continue;
    }

    try {
      const res = await fetch(
        `${KIE_BASE}/jobs/getTaskDetail?taskId=${tasks[i].taskId}`,
        { headers: { Authorization: `Bearer ${KIE_API_KEY}` } }
      );
      if (!res.ok) continue;

      const json = await res.json();
      const status = (json?.data?.status ?? '').toUpperCase();

      if (status === 'SUCCESS' || status === 'COMPLETED') {
        const output = json?.data?.output;
        tasks[i].imageUrl = Array.isArray(output) ? output[0] : output;
        done.push(i);
      } else if (status === 'FAILED' || status === 'ERROR') {
        console.error(`Task ${i} (row ${tasks[i].rowId}) failed on Kie AI`);
        tasks[i].failed = true;
        done.push(i);
      }
    } catch (e) {
      console.error(`Poll error task ${i}: ${e.message}`);
    }
  }

  for (const i of done) pending.delete(i);
}

// ── 5. Retry failed tasks (up to MAX_RETRIES times) ──────
const failedTasks = tasks.filter((t) => !t.imageUrl && t.retries < MAX_RETRIES);

for (const task of failedTasks) {
  let imageUrl = null;

  for (let attempt = 1; attempt <= MAX_RETRIES; attempt++) {
    await sleep(2000 * attempt); // back-off
    try {
      const createRes = await fetch(`${KIE_BASE}/jobs/createTask`, {
        method: 'POST',
        headers: { Authorization: `Bearer ${KIE_API_KEY}`, 'Content-Type': 'application/json' },
        body: JSON.stringify({
          model: 'nano-banana-2',
          input: {
            prompt: task.prompt,
            image_input: CHARACTER_REF_URL ? [CHARACTER_REF_URL] : [],
            aspect_ratio: 'auto',
            resolution: '1K',
            output_format: 'png',
          },
        }),
      });
      if (!createRes.ok) continue;
      const createJson = await createRes.json();
      const retryTaskId = createJson?.data?.taskId ?? createJson?.taskId;
      if (!retryTaskId) continue;

      // Poll this retry
      for (let p = 0; p < MAX_POLL_ATTEMPTS; p++) {
        await sleep(POLL_INTERVAL_MS);
        const pollRes = await fetch(
          `${KIE_BASE}/jobs/getTaskDetail?taskId=${retryTaskId}`,
          { headers: { Authorization: `Bearer ${KIE_API_KEY}` } }
        );
        if (!pollRes.ok) continue;
        const pollJson = await pollRes.json();
        const st = (pollJson?.data?.status ?? '').toUpperCase();
        if (st === 'SUCCESS' || st === 'COMPLETED') {
          const output = pollJson?.data?.output;
          imageUrl = Array.isArray(output) ? output[0] : output;
          break;
        } else if (st === 'FAILED' || st === 'ERROR') {
          break;
        }
      }
      if (imageUrl) break;
    } catch (e) {
      console.error(`Retry ${attempt} error for row ${task.rowId}: ${e.message}`);
    }
  }

  task.imageUrl = imageUrl ?? null;
}

// ── 6. Write results back to Baserow ─────────────────────
let completed = 0;
let failed = 0;

for (const task of tasks) {
  if (task.imageUrl) {
    await brPatch(task.rowId, { status: 'completed', image_url: task.imageUrl });
    completed++;
  } else {
    await brPatch(task.rowId, { status: 'failed' });
    failed++;
  }
  await sleep(100);
}

return [{
  json: {
    message: `Done. ${completed} completed, ${failed} failed out of ${tasks.length} rows.`,
    completed,
    failed,
    total: tasks.length,
  },
}];
